@push('scripts')<script>document.querySelectorAll('[data-count]').forEach(el=>{const target=Number(el.dataset.count||0);if(!target)return;const start=performance.now(),duration=650;function tick(now){const p=Math.min((now-start)/duration,1);el.textContent=Math.round(target*(1-Math.pow(1-p,3))).toLocaleString('id-ID');if(p<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)});</script>@endpush
